async function exportArchiveImage(){const canvas=await buildArchiveCanvas();const filename=`${state.meta.name||'钢神人物'}-档案总览.png`;if(canvas.toBlob){canvas.toBlob(blob=>{if(!blob){download(filename,canvas.toDataURL('image/png'),'image/png');return}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1600)},'image/png')}else{download(filename,canvas.toDataURL('image/png'),'image/png')}toast('档案总览图已开始导出')}
// Fully offline, multipage A4 PDF; rasterises the same archive used by PNG export.
// Pages are independent JPEG XObjects embedded into a standards-compliant PDF 1.4.
async function exportArchivePDF(){
 const canvas=await buildArchiveCanvas();
 const paperW=595.28,paperH=841.89,margin=24,drawW=paperW-2*margin;
 const maxSlicePx=Math.floor((paperH-2*margin)*canvas.width/drawW);
 const encoder=new TextEncoder();const parts=[];const offsets=[0];let bytes=0;
 const push=v=>{const a=typeof v==='string'?encoder.encode(v):v;parts.push(a);bytes+=a.byteLength};
 const begin=(id,body)=>{offsets[id]=bytes;push(`${id} 0 obj\n`);push(body);push('\nendobj\n')};
 const pageCount=Math.ceil(canvas.height/maxSlicePx);
 const children=Array.from({length:pageCount},(_,i)=>`${3+3*i} 0 R`).join(' ');
 push('%PDF-1.4\n%');push(new Uint8Array([0xe2,0xe3,0xcf,0xd3]));push('\n');
 begin(1,'<< /Type /Catalog /Pages 2 0 R >>');
 begin(2,`<< /Type /Pages /Kids [${children}] /Count ${pageCount} >>`);
 for(let i=0;i<pageCount;i++){
  const sourceY=i*maxSlicePx,sh=Math.min(maxSlicePx,canvas.height-sourceY);
  const pageCanvas=document.createElement('canvas');pageCanvas.width=canvas.width;pageCanvas.height=sh;
  const ctx=pageCanvas.getContext('2d');ctx.fillStyle='#f8f2e7';ctx.fillRect(0,0,canvas.width,sh);
  ctx.drawImage(canvas,0,sourceY,canvas.width,sh,0,0,canvas.width,sh);
  const url=pageCanvas.toDataURL('image/jpeg',0.88);
  if(!url.startsWith('data:image/jpeg;base64,'))throw Error('此浏览器不支持生成 PDF 所需的 JPEG 图片');
  const binary=atob(url.split(',')[1]),jpg=new Uint8Array(binary.length);
  for(let j=0;j<binary.length;j++)jpg[j]=binary.charCodeAt(j);
  const pageId=3+3*i,imageId=pageId+1,contentId=pageId+2;
  const drawH=sh*drawW/canvas.width,y=paperH-margin-drawH;
  begin(pageId,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${paperW} ${paperH}] /Resources << /XObject << /Im0 ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`);
  offsets[imageId]=bytes;push(`${imageId} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${sh} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);push(jpg);push('\nendstream\nendobj\n');
  const content=`q\n${drawW.toFixed(4)} 0 0 ${drawH.toFixed(4)} ${margin.toFixed(4)} ${y.toFixed(4)} cm\n/Im0 Do\nQ\n`;
  const contentBytes=encoder.encode(content);
  offsets[contentId]=bytes;push(`${contentId} 0 obj\n<< /Length ${contentBytes.length} >>\nstream\n`);push(contentBytes);push('endstream\nendobj\n');
 }
 const xrefStart=bytes,maxID=2+3*pageCount;
 push(`xref\n0 ${maxID+1}\n0000000000 65535 f \n`);
 for(let i=1;i<=maxID;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);
 push(`trailer\n<< /Size ${maxID+1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`);
 const file=new Blob(parts,{type:'application/pdf'}),url=URL.createObjectURL(file),a=document.createElement('a');
 a.href=url;a.download=`${String(state.meta.name||'钢神人物').replace(/[\\/:*?"<>|]/g,'_')}-档案总览.pdf`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);
 toast(`PDF 已导出（A4 · ${pageCount} 页）`);
}
function renderExport(){const commands=packCommands();return panel('跨端与移动端使用',`<div class="notice"><b>当前版本已经支持移动端自适应。</b> 手机上会自动切换为更紧凑的顶部与单栏 / 双栏布局；表格区域保留横向滚动，方便在小屏设备上查看完整数值。</div><div class="toolbar">${action('↓ 下载当前人物存档','data-action="backup"','primary')}${action('↓ 批量备份全部人物','data-library-action="backup-all"')}${action('↗ 人物档案库','data-go="library"')}${action('↑ 导入人物存档','data-action="restore"')}${action('↓ 下载角色指令','data-action="download-command"')}</div><p class="mini">人物存档包含人物设定、类别、所有自定义装备、特技、物品、连招与仆从；不要把自己的存档 JSON 公开上传到 GitHub 仓库。若要换设备，请使用“下载人物存档 → 导入人物存档”的方式迁移。</p>`)+panel('档案总览图导出',`<div class="notice warn"><b>一键导出 PNG 档案图。</b> 系统会把人物头像、机体图、核心资料、类别、属性、战斗值、关键装备、加护与特技摘要整理成一整张图片，适合发群、留档和跨平台查看。</div><div class="toolbar">${action('🖼️ 导出档案总览图 PNG','data-action="export-image"','primary')}${action('📄 导出 A4 PDF','data-action="export-pdf"')}</div><p class="mini">PNG 与 PDF 均包含人物影像、机体影像、战斗值和完整背景文字；特技及物品仅展示摘要。PDF 为适合打印的 A4 多页图片式档案，无须联网。</p>`)+panel('机器人指令导出',`<div class="toolbar">${action('复制全部建卡指令','data-copy="all"','primary')}${action('复制人物数据','data-copy="character"')}${action('复制装备数据库','data-copy="equipment"')}</div><h3>人物卡数据 · .pgfj人物</h3><pre class="output">${h(commands.character)}</pre><h3>自定义装备数据库 · .pgfj物品</h3><pre class="output">${h(commands.equipment)}</pre><h3>装备组指令 · .SvW</h3><div class="notice">每个装备组对应一条 <b>.SvW W{装备组名称}{配装JSON}</b> 指令。请先在机体配装页保存装备组，再点击对应组的「复制本条指令」，<b>逐条发送到骰子中</b>，不要将所有指令合并为一条。</div>${exportGearSets()}`)+panel('战斗 Combio 指令',`${state.combos.length?state.combos.map((x,i)=>`<div class="toolbar"><span class="tag">Combio ${i+1}: ${h(x.name)}</span><button class="btn small" data-copy-combo="${i}">复制</button></div><pre class="output">${h(comboCommand(x))}</pre>`).join(''):'<p class="mini">目前没有建立连招，前往“战斗 Combio”填写后可生成指令。</p>'}`)}
function ruleCatalog(){let q=ui.ruleQuery.trim().toLowerCase();const t=ui.ruleType;let x=[];if(t==='类别信息')x=DB.classes.map(r=>({名称:r.名称,信息:`加护：${r.加护} / 基础：${ATTR.map(s=>s+' '+r.属性[s]).join(' · ')}`,效果:r.说明||''}));else if(t==='加护列表')x=DB.blessings.map(r=>({名称:r.名称,信息:r.时点+' · '+r.对象,效果:r.效果}));else if(t==='特技表')x=DB.skills.map(r=>({名称:r.名称,信息:`${r.类别} · ${r.等级}级 · ${r.时点} · ${r.代价}`,效果:r.效果}));else if(t==='生活方式')x=DB.lifestyles.map(r=>({名称:r.名称,信息:`常备 ${r.常备} · 财产 ${r.财产}`,效果:r.解说}));else if(t==='住宅')x=DB.homes.map(r=>({名称:r.名称,信息:`常备 ${r.常备}`,效果:r.解说}));else if(t==='成长')x=Object.entries(DB.growth).map(([name,vals])=>({名称:name,信息:'1~20 级类别成长',效果:STATS.map(s=>`${s}: ${vals[s]?.join('/')||'暂无'}`).join('；')}));else if(DB.equipment[t])x=equipmentList(t).map(r=>({名称:r.名称,信息:t,效果:Object.entries(r).filter(([k])=>k!=='名称').map(([k,v])=>k+': '+v).join(' · ')}));return x.filter(r=>!q||Object.values(r).some(v=>String(v).toLowerCase().includes(q))).slice(0,120).map(r=>`<div class="catalogitem"><div><h4>${h(r.名称)} <small>${h(r.信息)}</small></h4><p>${h(r.效果)}</p></div></div>`).join('')||'<div class="empty">未找到匹配结果。</div>'}
function renderReference(){const types=['类别信息','成长','加护列表','特技表','生活方式','住宅',...DBKINDS];return panel('原表规则查询',`<div class="notice">本页为只读数据库检索，可查看从原 Excel 提取的全部类别、成长值、特技、加护及装备模板；配装页可编辑自定义装备。</div><div class="toolbar"><select class="search" id="rule-type" style="max-width:200px">${types.map(k=>option(k,k,ui.ruleType)).join('')}</select><input class="search" id="rule-search" value="${h(ui.ruleQuery)}" placeholder="搜索名称或规则关键词"></div><div class="catalog" id="rule-list">${ruleCatalog()}</div>`)}
function updateNav(){document.querySelectorAll('.navlink').forEach(el=>el.classList.toggle('active',el.dataset.go===ui.page))}
function growItemEffects(root=document){root.querySelectorAll('textarea[data-autogrow="item-effect"]').forEach(el=>{el.style.height='auto';el.style.height=Math.max(110,el.scrollHeight+2)+'px'})}
function render(){const functions={library:renderLibrary,home:renderHome,character:renderCharacter,career:renderCareer,equipment:renderEquipment,combat:renderCombat,skills:renderSkills,items:renderItems,combos:renderCombos,servant:renderServant,export:renderExport,reference:renderReference};document.querySelector('#page-title').textContent=PANEL[ui.page][0];const content=document.querySelector('#page-content');content.innerHTML=functions[ui.page]();updateNav();document.querySelector('#small-name').textContent=state.meta.name||'未命名连结者';if(ui.page==='items')growItemEffects(content);} 
async function nav(page){if(libDB&&!activeCharacterId&&page!=='library'){toast('请先创建或导入人物档案');page='library'}if(page==='library'&&libDB&&activeCharacterId){try{await flushCurrent()}catch(err){alert('当前人物保存失败，请先导出单人物 JSON 备份再切换：'+err.message);return}}ui.page=page;render();window.scrollTo({top:0,behavior:'auto'})}
function toast(msg){const x=document.createElement('div');x.className='toast';x.textContent=msg;document.body.append(x);setTimeout(()=>x.remove(),2800)}
function download(name,contents,type='application/json'){const blob=new Blob([contents],{type:type+';charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板')}catch{const ta=document.createElement('textarea');ta.value=text;document.body.append(ta);ta.select();let ok=document.execCommand('copy');ta.remove();toast(ok?'已复制到剪贴板':'复制失败，请使用导出存档功能')}}
function handleEvent(e){const el=e.target;if(!el.matches('input,select,textarea'))return;
 if(el.id==='gear-set-name'){ui.gearName=el.value;return}
 if(el.dataset.originIndex!==undefined){if(e.type==='change')setOriginByIndex(el.value);return}
 if(/^careers\.\d+\.(initial|growth)$/.test(el.dataset.path||'')){
   if(e.type!=='change')return;
   const old=deepGet(state,el.dataset.path),v=Number(el.value);
   if(!Number.isInteger(v)||v<0){el.value=old;toast('类别等级必须是非负整数');return}
   pathSet(el.dataset.path,v);const totals=categoryTotals();
   if(!totals.valid){pathSet(el.dataset.path,old);el.value=old;toast(totals.initial>3?'初始等级合计不能超过 3':'类别总等级不能超过 20');return}
   save();render();return
 }

 if(el.dataset.path){let old=deepGet(state,el.dataset.path);const v=el.type==='number'?toNum(el.value):el.value;pathSet(el.dataset.path,v);if(el.dataset.path==='meta.lifestyle'||el.dataset.path==='meta.home')syncLinkedItems();save();if(el.dataset.path==='meta.name'){const sig=document.querySelector('#live-signature');if(sig)sig.textContent=v||'待签署'}if(el.dataset.path==='meta.summary'||el.dataset.path==='meta.background'){const preview=document.querySelector(el.dataset.path==='meta.summary'?'#live-background-summary':'#live-background-detail');if(preview)preview.textContent=v||'尚未填写'}if(e.type==='change')render();return}
 if(el.dataset.skill!==undefined){const i=Number(el.dataset.skill);if(state.skills[i]){state.skills[i][el.dataset.skillkey]=el.type==='number'?toNum(el.value):el.value;save();if(el.dataset.skillkey==='name'&&e.type==='input'){const strong=el.closest('.skill-file')?.querySelector('summary strong');if(strong)strong.textContent=el.value;}}return}
 if(el.dataset.slot){state.slots[el.dataset.slot]=el.value;save();render();return}
 if(el.dataset.customkey){const record=state.custom[ui.kind].find(x=>x.名称===ui.editor);if(record){const key=el.dataset.customkey;if(key==='名称'){if(e.type!=='change')return;const next=el.value.trim(),old=ui.editor;if(!next||equipmentList(ui.kind).some(x=>x!==record&&x.名称===next)){el.value=old;toast('装备名称不能为空或与现有装备重复');return}record.名称=next;if(record.型号===old)record.型号=next;for(const [slot,v] of Object.entries(state.slots))if(v===old&&SLOT_TYPES[slot]===ui.kind)state.slots[slot]=next;for(const set of state.equipmentSets)for(const [slot,v] of Object.entries(set.slots))if(v===old&&SLOT_TYPES[slot]===ui.kind)set.slots[slot]=next;ui.editor=next;save();render();return}record[key]=el.type==='number'?toNum(el.value):el.value;save();if(e.type==='change')render()}return}
 for(const [type,key,arr] of [['item','itemkey','items'],['combo','combokey','combos'],['servant','servantkey','servants']]){if(el.dataset[type]!==undefined){const i=Number(el.dataset[type]);if(state[arr][i]){state[arr][i][el.dataset[key]]=el.type==='number'?toNum(el.value):el.value;save();if(type==='item'&&el.dataset[key]==='effect'&&e.type==='input')growItemEffects(el.parentElement);if(type==='item'&&e.type==='input'&&(el.dataset[key]==='name'||el.dataset[key]==='kind')){const card=el.closest('.item-record');const heading=card?.querySelector('.item-record-heading strong');const kindText=card?.querySelector('.item-kind-suffix');if(heading)heading.textContent=state.items[i].name||'未命名物品';if(kindText)kindText.textContent=String(state.items[i].kind||'').trim()||'未分类';const summary=card?.querySelector('summary');if(summary)summary.setAttribute('aria-label',(state.items[i].name||'未命名物品')+' ['+(String(state.items[i].kind||'').trim()||'未分类')+']，展开查看与编辑')}if(e.type==='change'&&(type!=='item'||el.dataset[key]==='cost'||el.dataset[key]==='quantity'))render()}return}}
 if(el.id==='skill-search'){ui.skillQuery=el.value;document.querySelector('#catalog-list').innerHTML=skillCatalog()}
 if(el.id==='rule-search'){ui.ruleQuery=el.value;document.querySelector('#rule-list').innerHTML=ruleCatalog()}
 if(el.id==='rule-type'){ui.ruleType=el.value;document.querySelector('#rule-list').innerHTML=ruleCatalog()}
}
document.addEventListener('input',handleEvent);document.addEventListener('change',handleEvent);
document.addEventListener('toggle',e=>{const el=e.target;if(!el.matches?.('details[data-item-record]')||!el.isConnected)return;const i=Number(el.dataset.itemRecord);if(el.open){ui.openItems.add(i);growItemEffects(el)}else ui.openItems.delete(i)},true);
window.addEventListener('resize',()=>{if(ui.page==='items')growItemEffects(document.querySelector('#page-content'))});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.go){nav(b.dataset.go);return}
 if(b.dataset.libraryAction){runLibraryAction(b.dataset.libraryAction,b.dataset.libraryId);return}
 if(b.dataset.kind){ui.kind=b.dataset.kind;ui.editor='';render();return}
 if(b.dataset.editor){ui.editor=b.dataset.editor;render();return}
 if(b.dataset.addSkill!==undefined){const d=DB.skills[Number(b.dataset.addSkill)];if(d){state.skills.push(skillFromDB(d));ui.openSkill=state.skills.length-1;save();render();toast('特技已加入人物档案，可编辑全部字段')}return}
 if(b.dataset.removeSkill!==undefined){if(!confirm('确定删除这条已登记特技？'))return;state.skills.splice(Number(b.dataset.removeSkill),1);ui.openSkill=-1;save();render();return}
 if(b.dataset.delItem!==undefined){const idx=Number(b.dataset.delItem);if(['lifestyle','home'].includes(state.items[idx]?.autoSource))return toast('自动关联物品请在人物资料页修改生活方式或住宅');state.items.splice(idx,1);ui.openItems=new Set([...ui.openItems].filter(i=>i!==idx).map(i=>i>idx?i-1:i));save();render();return}
 if(b.dataset.delCombo!==undefined){state.combos.splice(Number(b.dataset.delCombo),1);save();render();return}
 if(b.dataset.delServant!==undefined){state.servants.splice(Number(b.dataset.delServant),1);save();render();return}
 if(b.dataset.copyCombo!==undefined){copy(comboCommand(state.combos[Number(b.dataset.copyCombo)]));return}
 if(b.dataset.uploadServant!==undefined){const input=document.querySelector(`input[data-servant-image="${b.dataset.uploadServant}"]`);if(input)input.click();return}
 if(b.dataset.removeServantImage!==undefined){const servant=state.servants[Number(b.dataset.removeServantImage)];if(servant&&confirm('确认删除这名仆从的头像？')){servant.image='';save();render()}return}
 if(b.dataset.copy){const co=packCommands();copy(b.dataset.copy==='all'?co.character+'\n'+co.equipment:co[b.dataset.copy]);return}
 if(b.dataset.loadSet!==undefined){const set=state.equipmentSets[Number(b.dataset.loadSet)];if(set){state.slots={...state.slots,...clone(set.slots)};state.activeEquipSet=set.name;ui.gearName=set.name;save();render();toast('已切换装备组：'+set.name)}return}
 if(b.dataset.deleteSet!==undefined){const ix=Number(b.dataset.deleteSet),set=state.equipmentSets[ix];if(set&&confirm('删除已保存的装备组“'+set.name+'”？不会删除当前已装备项目。')){state.equipmentSets.splice(ix,1);if(state.activeEquipSet===set.name)state.activeEquipSet='';save();render()}return}
 if(b.dataset.copySet!==undefined){const set=state.equipmentSets.length?state.equipmentSets[Number(b.dataset.copySet)]:{name:'通常',slots:state.slots};if(set)copy(equipmentSetCommand(set));return}
 if(b.dataset.action==='save-gear-set'){const name=(document.querySelector('#gear-set-name')?.value||'').trim();if(!name)return toast('请输入装备组名称');if(name.length>36||/[{}\r\n]/.test(name))return toast('装备组名称不能含有大括号或换行，最多 36 字');const ix=state.equipmentSets.findIndex(x=>x.name===name);if(ix>=0&&!confirm('装备组“'+name+'”已存在，是否覆盖保存？'))return;const set={name,slots:clone(state.slots)};if(ix>=0)state.equipmentSets[ix]=set;else state.equipmentSets.push(set);state.activeEquipSet=name;ui.gearName=name;save();render();toast('已保存装备组：'+name);return}
 if(b.dataset.action==='add-skill'){state.skills.push(skillFromDB({名称:'',等级:1}));ui.openSkill=state.skills.length-1;save();render();return}
 if(b.dataset.upload){document.querySelector('#image-'+b.dataset.upload).click();return}
 if(b.dataset.removeMedia){if(!confirm('确认移除这张档案图片？'))return;state.media[b.dataset.removeMedia]='';save();render();return}
 if(b.dataset.action==='add-item'){state.items.push({name:'新物品',kind:'',timing:'',target:'',difficulty:'',cost:0,quantity:1,used:0,effect:''});ui.openItems.add(state.items.length-1);save();render();return}
 if(b.dataset.action==='add-combo'){state.combos.push({name:'',weapon:'',attack:0,damage:'',en:0,hp:0,quote:'',notes:''});save();render();return}
 if(b.dataset.action==='add-servant'){state.servants.push({name:'',template:'',level:1,fp:0,hp:0,en:0,action:0,attack:0,hit:0,dodge:0,shoot:0,shield:0,story:'',powers:'',image:''});save();render();return}
 if(b.dataset.action==='add-equip'){const raw=document.getElementById('new-equip-name')?.value.trim();if(!raw)return toast('请先输入装备名称');if(equipmentList(ui.kind).some(x=>x.名称===raw))return toast('装备名已存在，请改用其他名称');const model=document.getElementById('new-equip-model')?.value.trim()||raw;state.custom[ui.kind].push({名称:raw,型号:model});ui.editor=raw;save();render();toast('已创建 '+raw);return}
 if(b.dataset.action==='delete-equip'){if(!confirm('确定删除此自定义装备？已装备的同名项目将改为“无”。'))return;state.custom[ui.kind]=state.custom[ui.kind].filter(x=>x.名称!==ui.editor);for(const set of state.equipmentSets)for(const [slot,v] of Object.entries(set.slots))if(v===ui.editor&&SLOT_TYPES[slot]===ui.kind)set.slots[slot]='无';for(const [k,v] of Object.entries(state.slots))if(v===ui.editor&&SLOT_TYPES[k]===ui.kind)state.slots[k]='无';ui.editor='';save();render();return}
 if(b.dataset.action==='backup'){download(`${state.meta.name||'钢神人物'}-白卡存档.json`,JSON.stringify({format:'gsk-web-character-v1',savedAt:new Date().toISOString(),state},null,2));toast('人物存档已下载');return}
 if(b.dataset.action==='restore'){document.querySelector('#import-file').click();return}
 if(b.dataset.action==='download-command'){const co=packCommands();download(`${state.meta.name||'钢神人物'}-指令.txt`,co.character+'\n'+co.equipment+'\n'+(state.equipmentSets.length?state.equipmentSets.map(equipmentSetCommand).join('\n'):co.set),'text/plain');toast('指令文件已下载');return}
 if(b.dataset.action==='export-image'){exportArchiveImage().catch(err=>{console.error(err);alert('导出档案图失败：'+err.message)});return}
 if(b.dataset.action==='export-pdf'){exportArchivePDF().catch(err=>{console.error(err);alert('导出 PDF 失败：'+err.message)});return}
 if(b.dataset.action==='new'){runLibraryAction('new');return}
 if(b.dataset.action==='theme'){document.body.classList.toggle('night');try{localStorage.setItem('gsk-theme',document.body.classList.contains('night')?'night':'paper')}catch{}return}
});

async function processArchiveImage(file){if(!file.type.startsWith('image/'))throw Error('请选择图片文件');if(file.size>25*1024*1024)throw Error('图片过大，单张不得超过 25MB');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('文件读取失败'));reader.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(Error('图片无法解析'));el.src=raw});const limit=1100,scale=Math.min(1,limit/Math.max(img.width,img.height));const cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));const ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);ctx.drawImage(img,0,0,cv.width,cv.height);let encoded=cv.toDataURL('image/webp',.79);if(!encoded.startsWith('data:image/webp')){ctx.globalCompositeOperation='destination-over';ctx.fillStyle='#f8f2e5';ctx.fillRect(0,0,cv.width,cv.height);encoded=cv.toDataURL('image/jpeg',.77)}return encoded;}
for(const type of ['portrait','mecha']){const imageInput=document.querySelector('#image-'+type);if(!imageInput)continue;imageInput.addEventListener('change',async ev=>{const file=ev.target.files?.[0];if(!file)return;try{const uploadingFor=activeCharacterId;const encoded=await processArchiveImage(file);if(uploadingFor!==activeCharacterId)throw Error('上传图片期间切换了人物，请在目标档案重新上传');const old=state.media[type];state.media[type]=encoded;try{await persistCurrent()}catch(err){state.media[type]=old;throw Error('图片保存失败：'+err.message+'，建议先导出人物 JSON 备份')}render();toast('图片已附入人物档案')}catch(err){alert('上传失败：'+err.message)}finally{ev.target.value=''}});}
document.addEventListener('change',async ev=>{const input=ev.target.closest('input[data-servant-image]');if(!input)return;const file=input.files?.[0],idx=Number(input.dataset.servantImage);if(!file||!state.servants[idx])return;try{const uploadingFor=activeCharacterId;const encoded=await processArchiveImage(file);if(uploadingFor!==activeCharacterId||!state.servants[idx])throw Error('上传图片期间切换了人物，请在目标档案重新上传');const old=state.servants[idx].image||'';state.servants[idx].image=encoded;try{await persistCurrent()}catch(err){state.servants[idx].image=old;throw Error('头像保存失败：'+err.message+'，请先导出 JSON 备份')}render();toast('仆从头像已保存')}catch(err){alert('头像上传失败：'+err.message)}finally{input.value=''}});
// Mouse, keyboard and touch compatible dossier annotations.
const floatingTip=document.createElement('div');floatingTip.id='doc-tooltip';floatingTip.setAttribute('role','tooltip');document.body.append(floatingTip);let tipTarget=null,tipPinned=false;
function displayTip(el,ev,pin=false){if(!el||!el.dataset.tip)return;tipTarget=el;tipPinned=pin;floatingTip.textContent=el.dataset.tip.replaceAll('\\n','\n');floatingTip.classList.add('visible');const rect=el.getBoundingClientRect();let width=Math.min(360,window.innerWidth-24);floatingTip.style.maxWidth=width+'px';const w=floatingTip.offsetWidth,hg=floatingTip.offsetHeight;const left=Math.max(12,Math.min(rect.left,window.innerWidth-w-12));const below=rect.bottom+9,top=below+hg>window.innerHeight-12?Math.max(12,rect.top-hg-9):below;floatingTip.style.left=left+'px';floatingTip.style.top=Math.max(12,Math.min(top,window.innerHeight-hg-12))+'px';}
function hideTip(){floatingTip.classList.remove('visible');tipTarget=null;tipPinned=false;}
document.addEventListener('pointerover',ev=>{if(ev.pointerType==='touch'||tipPinned)return;const el=ev.target.closest('[data-tip]');if(el)displayTip(el,ev)});
document.addEventListener('pointerout',ev=>{if(tipPinned)return;const el=ev.target.closest('[data-tip]');if(el&&(!ev.relatedTarget||!el.contains(ev.relatedTarget)))hideTip()});
document.addEventListener('focusin',ev=>{const el=ev.target.closest('[data-tip]');if(el)displayTip(el,null)});
document.addEventListener('focusout',ev=>{if(!tipPinned)hideTip()});
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-tip]');if(el&&(!ev.target.closest('button[data-add-skill]'))){if(tipPinned&&tipTarget===el)hideTip();else displayTip(el,ev,true)}else if(tipPinned)hideTip();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')hideTip()});
document.addEventListener('scroll',()=>{if(!tipPinned)hideTip()},true);

document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const payload=JSON.parse(await file.text());await importArchivePayload(payload)}catch(err){console.error(err);alert('导入失败：'+err.message)}finally{e.target.value=''}});
try{if(localStorage.getItem('gsk-theme')==='night')document.body.classList.add('night')}catch{}
function initializeSidebar(){const node=document.querySelector('#navigation');if(!node)return;node.innerHTML=Object.entries(PANEL).map(([key,[txt,ico]])=>`<button type="button" class="navlink" data-go="${key}"><span class="symbol">${ico}</span><span>${txt}</span></button>`).join('');updateNav()}
initializeSidebar();
render();
bootArchiveLibrary();
